<?php $esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="admin-menu admin-page">
<header class="admin-page__header"><div><h1 class="admin-page__title">Recetario de la casa</h1><p class="admin-page__subtitle">Preparaciones estándar y sus versiones. Cada negocio mantiene su receta operativa y sus orígenes de consumo.</p></div><a class="admin-btn admin-btn--secondary" href="/admin/global/productos">Volver a productos</a></header>
<form method="GET" class="admin-filters"><label class="admin-field">Buscar producto<input type="search" name="q" maxlength="100" value="<?= $esc($q) ?>"></label><button class="admin-btn admin-btn--primary">Buscar</button></form>
<div class="admin-table-wrap"><table class="admin-table admin-catalogo-table"><thead><tr><th>Producto</th><th>Receta estándar</th><th>Última publicación</th><th>Acción</th></tr></thead><tbody><?php foreach($filasCasa as $fila): ?><tr><td data-label="Producto"><?= $esc($fila['nombre']) ?></td><td data-label="Receta estándar"><?= $fila['version']?'Versión '.(int)$fila['version']:'Sin publicación' ?><?= $fila['borrador']?' · Borrador disponible':'' ?></td><td data-label="Última publicación"><?= $esc($fila['fecha']??'Pendiente') ?></td><td data-label="Acción"><a class="admin-btn admin-btn--secondary" href="/admin/global/productos/receta?id=<?= (int)$fila['id'] ?>">Ver receta</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php if(!$filasCasa): ?><p class="admin-empty">No hay productos que coincidan. Crea un producto de la casa para preparar su receta.</p><?php endif; ?>
<nav class="admin-pagination" aria-label="Páginas del recetario"><span>Página <?= $pagina ?> de <?= $paginas ?></span><?php foreach(['Anterior'=>$pagina-1,'Siguiente'=>$pagina+1] as $texto=>$n): if($n<1||$n>$paginas)continue; ?><a class="admin-btn admin-btn--secondary" href="?<?= $esc(http_build_query(['q'=>$q,'page'=>$n])) ?>"><?= $texto ?></a><?php endforeach; ?></nav>
